          const roof = new THREE.Mesh(new THREE.BoxGeometry(w + 0.6, 0.5, d + 0.6), roofMat);
          roof.position.set(x, h + 0.25, z);
          scene.add(roof);
          if (rng() < 0.5) {
            const ac = new THREE.Mesh(new THREE.BoxGeometry(2.4, 1.2, 2.4), new THREE.MeshLambertMaterial({ color: 0x9aa0a8 }));
            ac.position.set(x + w / 4, h + 1, z - d / 4);
            ac.castShadow = true;
            scene.add(ac);
          }
          this.colliders.push({ minX: x - w / 2 - 0.4, maxX: x + w / 2 + 0.4, minZ: z - d / 2 - 0.4, maxZ: z + d / 2 + 0.4 });
        }
