    }

    // Palm rows along the beach and a few in parks.
    for (let x = -HALF; x <= HALF; x += 26) this.palm(x + (rng() - 0.5) * 8, HALF + 16 + rng() * 20);
    for (let i = 0; i < 26; i += 1) this.palm((rng() * 2 - 1) * (HALF - 20), (rng() * 2 - 1) * (HALF - 20));

    // Street lamps at intersections.
    const poleMat = new THREE.MeshLambertMaterial({ color: 0x2b2f36 });
    const lampMat = new THREE.MeshLambertMaterial({ color: 0xfff6c9, emissive: 0xccaa55 });
    for (const x of ROADS) {
      for (const z of ROADS) {
        if (rng() < 0.6) continue;
        const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.12, 6, 6), poleMat);
        pole.position.set(x + CITY.road / 2 + 1, 3, z + CITY.road / 2 + 1);
        scene.add(pole);
        const lamp = new THREE.Mesh(new THREE.SphereGeometry(0.35, 8, 6), lampMat);
        lamp.position.set(x + CITY.road / 2 + 1, 6.1, z + CITY.road / 2 + 1);
